__global__ void splitim_piece4(Fp* check, const Fp* ctrl, const Fp* data, const Fp* accum, const Fp* mix,
    const Fp* out, const Fp rou, uint32_t po2, uint32_t domain, uint32_t base, uint32_t rows) {
