// Host launcher. Runs every piece over one chunk of rows, then the next chunk; the carry holds one chunk.
// carry_bytes caps the carry buffer (the chunk is the largest power of two that fits, at least 1024 rows).
extern "C" const char* splitim_eval_check(Fp* check, const Fp* ctrl, const Fp* data, const Fp* accum,
                                      const Fp* mix, const Fp* out, const Fp& rou, uint32_t po2,
                                      uint32_t domain, size_t carry_bytes) {
  try {
    static Fp* carry = nullptr;
    static size_t carry_have = 0;
    uint32_t chunk = domain;
    while (chunk > 1024 && (size_t)chunk * splitim_kCarryCols * sizeof(Fp) > carry_bytes) chunk >>= 1;
    size_t need = (size_t)chunk * (splitim_kCarryCols ? splitim_kCarryCols : 1) * sizeof(Fp);
    if (need > carry_have) {
      if (carry) CUDA_OK(cudaFree(carry));
      carry = nullptr; carry_have = 0;
      CUDA_OK(cudaMalloc(&carry, need));
      carry_have = need;
    }
    CudaStream stream;
    CUDA_OK(cudaMemcpyToSymbolAsync(splitim_carry, &carry, sizeof(carry), 0, cudaMemcpyHostToDevice, stream));
    CUDA_OK(cudaMemcpyToSymbolAsync(splitim_stride, &chunk, sizeof(chunk), 0, cudaMemcpyHostToDevice, stream));
    auto cfg = getSimpleConfig(chunk);
    for (uint32_t base = 0; base < domain; base += chunk) {
      splitim_piece0<<<cfg.grid, cfg.block, 0, stream>>>(check, ctrl, data, accum, mix, out, rou, po2, domain, base, chunk);
      splitim_piece1<<<cfg.grid, cfg.block, 0, stream>>>(check, ctrl, data, accum, mix, out, rou, po2, domain, base, chunk);
      splitim_piece2<<<cfg.grid, cfg.block, 0, stream>>>(check, ctrl, data, accum, mix, out, rou, po2, domain, base, chunk);
      splitim_piece3<<<cfg.grid, cfg.block, 0, stream>>>(check, ctrl, data, accum, mix, out, rou, po2, domain, base, chunk);
      splitim_piece4<<<cfg.grid, cfg.block, 0, stream>>>(check, ctrl, data, accum, mix, out, rou, po2, domain, base, chunk);
    }
    CUDA_OK(cudaPeekAtLastError());
    CUDA_OK(cudaStreamSynchronize(stream));
  } catch (const std::exception& err) {
    return strdup(err.what());
  } catch (...) {
    return strdup("Generic exception");
  }
  return nullptr;
}
extern "C" uint32_t splitim_carry_cols() { return splitim_kCarryCols; }
